def imprimir_linhas_numeradas(caminho):
    with open(caminho) as arquivo:
        for numero, linha in enumerate(arquivo, start=1):
            print(numero, linha.strip())

def processar_lote(pedidos):
    validos = []
    rejeitados = []
    for pedido in pedidos:
        try:
            resultado = validar_pedido(pedido)
            validos.append(resultado)
        except KeyError:
            rejeitados.append({'id': pedido.get('id_pedido'), 'motivo': 'campo obrigatorio ausente'})
        except ValueError:
            rejeitados.append({'id': pedido.get('id_pedido'), 'motivo': 'valor invalido'})
    return validos, rejeitados
